package com.nequard.topology;
import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="topology_links") public class TopologyLink{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)UUID sourceDeviceId;@Column(nullable=false)UUID targetDeviceId;Double bandwidthMbps,latencyMs,packetLossPercent,utilizationPercent;String status="UP",discoveryMethod="MANUAL";public UUID getId(){return id;}public UUID getSourceDeviceId(){return sourceDeviceId;}public void setSourceDeviceId(UUID v){sourceDeviceId=v;}public UUID getTargetDeviceId(){return targetDeviceId;}public void setTargetDeviceId(UUID v){targetDeviceId=v;}public Double getBandwidthMbps(){return bandwidthMbps;}public void setBandwidthMbps(Double v){bandwidthMbps=v;}public Double getLatencyMs(){return latencyMs;}public void setLatencyMs(Double v){latencyMs=v;}public Double getPacketLossPercent(){return packetLossPercent;}public void setPacketLossPercent(Double v){packetLossPercent=v;}public Double getUtilizationPercent(){return utilizationPercent;}public void setUtilizationPercent(Double v){utilizationPercent=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getDiscoveryMethod(){return discoveryMethod;}public void setDiscoveryMethod(String v){discoveryMethod=v;}}
